// src/lib.rs
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::RwLock;
use tokio::task::JoinHandle;
use tokio::time;

pub type EvictionCallback = Arc<dyn Fn(String, EvictionReason) + Send + Sync>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

impl EvictionReason {
    pub fn as_str(&self) -> &'static str {
        match self {
            EvictionReason::Expired => "expired",
            EvictionReason::Lru => "lru",
            EvictionReason::Memory => "memory",
        }
    }
}

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

#[derive(Clone)]
pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<EvictionCallback>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_millis(60000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5000),
            on_evict: None,
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

pub struct LRUCache<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: VecDeque<String>,
    config: CacheConfig,
    current_memory: usize,
    stats: CacheStats,
}

impl<V> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            entries: HashMap::new(),
            access_order: VecDeque::new(),
            config,
            current_memory: 0,
            stats: CacheStats::default(),
        }
    }

    pub fn get(&mut self, key: &str) -> Option<&V> {
        let now = Instant::now();

        if let Some(entry) = self.entries.get(key) {
            if now > entry.expires_at {
                self.delete_internal(key, EvictionReason::Expired);
                self.stats.misses += 1;
                return None;
            }
        } else {
            self.stats.misses += 1;
            return None;
        }

        // Update entry after expiration check
        if let Some(entry) = self.entries.get_mut(key) {
            entry.last_accessed = now;
            entry.access_count += 1;
        }

        self.move_to_front(key);
        self.stats.hits += 1;

        self.entries.get(key).map(|e| &e.value)
    }

    pub fn put(&mut self, key: String, value: V, ttl: Option<Duration>, size: Option<usize>) 
    where
        V: EstimateSize,
    {
        let size = size.unwrap_or_else(|| value.estimate_size());
        let ttl = ttl.unwrap_or(self.config.default_ttl);

        // Remove old entry if exists
        if self.entries.contains_key(&key) {
            if let Some(old) = self.entries.get(&key) {
                self.current_memory -= old.size;
            }
        }

        // Evict for memory
        while self.current_memory + size > self.config.max_memory_bytes 
            && !self.access_order.is_empty() {
            self.evict_lru(EvictionReason::Memory);
        }

        // Evict for max entries
        while self.entries.len() >= self.config.max_entries 
            && !self.access_order.is_empty() 
            && !self.entries.contains_key(&key) {
            self.evict_lru(EvictionReason::Lru);
        }

        let now = Instant::now();
        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        self.current_memory += size;
        self.entries.insert(key.clone(), entry);
        self.move_to_front(&key);
    }

    pub fn delete(&mut self, key: &str) -> bool {
        self.delete_internal(key, EvictionReason::Lru)
    }

    pub fn has(&mut self, key: &str) -> bool {
        if let Some(entry) = self.entries.get(key) {
            if Instant::now() > entry.expires_at {
                self.delete_internal(key, EvictionReason::Expired);
                return false;
            }
            true
        } else {
            false
        }
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn memory_usage(&self) -> usize {
        self.current_memory
    }

    pub fn get_stats(&self) -> CacheStats {
        CacheStats {
            hits: self.stats.hits,
            misses: self.stats.misses,
            evictions: self.stats.evictions,
            expirations: self.stats.expirations,
            size: self.entries.len(),
            memory: self.current_memory,
        }
    }

    pub fn clear(&mut self) {
        let keys: Vec<String> = self.entries.keys().cloned().collect();
        for key in keys {
            self.delete_internal(&key, EvictionReason::Lru);
        }
    }

    pub fn keys(&self) -> Vec<String> {
        self.access_order.iter().cloned().collect()
    }

    pub fn evict_expired(&mut self) {
        let now = Instant::now();
        let expired: Vec<String> = self
            .entries
            .iter()
            .filter(|(_, entry)| now > entry.expires_at)
            .map(|(key, _)| key.clone())
            .collect();

        for key in expired {
            self.delete_internal(&key, EvictionReason::Expired);
        }
    }

    fn delete_internal(&mut self, key: &str, reason: EvictionReason) -> bool {
        if let Some(entry) = self.entries.remove(key) {
            self.current_memory -= entry.size;
            self.access_order.retain(|k| k != key);

            match reason {
                EvictionReason::Expired => self.stats.expirations += 1,
                _ => self.stats.evictions += 1,
            }

            if let Some(ref callback) = self.config.on_evict {
                callback(key.to_string(), reason);
            }

            true
        } else {
            false
        }
    }

    fn move_to_front(&mut self, key: &str) {
        self.access_order.retain(|k| k != key);
        self.access_order.push_front(key.to_string());
    }

    fn evict_lru(&mut self, reason: EvictionReason) {
        if let Some(oldest) = self.access_order.pop_back() {
            self.delete_internal(&oldest, reason);
        }
    }
}

pub trait EstimateSize {
    fn estimate_size(&self) -> usize;
}

impl EstimateSize for String {
    fn estimate_size(&self) -> usize {
        self.len() * 2
    }
}

impl EstimateSize for &str {
    fn estimate_size(&self) -> usize {
        self.len() * 2
    }
}

impl EstimateSize for i32 {
    fn estimate_size(&self) -> usize {
        8
    }
}

impl EstimateSize for i64 {
    fn estimate_size(&self) -> usize {
        8
    }
}

impl EstimateSize for f64 {
    fn estimate_size(&self) -> usize {
        8
    }
}

impl EstimateSize for bool {
    fn estimate_size(&self) -> usize {
        4
    }
}

impl<T: serde::Serialize> EstimateSize for T {
    fn estimate_size(&self) -> usize {
        serde_json::to_string(self)
            .map(|s| s.len() * 2)
            .unwrap_or(0)
    }
}

pub struct AsyncLRUCache<V> {
    inner: Arc<RwLock<LRUCache<V>>>,
    eviction_task: Arc<RwLock<Option<JoinHandle<()>>>>,
}

impl<V: Send + 'static> AsyncLRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(RwLock::new(LRUCache::new(config))),
            eviction_task: Arc::new(RwLock::new(None)),
        }
    }

    pub async fn get(&self, key: &str) -> Option<V> 
    where
        V: Clone,
    {
        let mut cache = self.inner.write().await;
        cache.get(key).cloned()
    }

    pub async fn get_ref<F, R>(&self, key: &str, f: F) -> Option<R>
    where
        F: FnOnce(&V) -> R,
    {
        let mut cache = self.inner.write().await;
        cache.get(key).map(f)
    }

    pub async fn put(&self, key: String, value: V, ttl: Option<Duration>, size: Option<usize>)
    where
        V: EstimateSize,
    {
        let mut cache = self.inner.write().await;
        cache.put(key, value, ttl, size);
    }

    pub async fn delete(&self, key: &str) -> bool {
        let mut cache = self.inner.write().await;
        cache.delete(key)
    }

    pub async fn has(&self, key: &str) -> bool {
        let mut cache = self.inner.write().await;
        cache.has(key)
    }

    pub async fn size(&self) -> usize {
        let cache = self.inner.read().await;
        cache.size()
    }

    pub async fn memory_usage(&self) -> usize {
        let cache = self.inner.read().await;
        cache.memory_usage()
    }

    pub async fn get_stats(&self) -> CacheStats {
        let cache = self.inner.read().await;
        cache.get_stats()
    }

    pub async fn clear(&self) {
        let mut cache = self.inner.write().await;
        cache.clear();
    }

    pub async fn keys(&self) -> Vec<String> {
        let cache = self.inner.read().await;
        cache.keys()
    }

    pub async fn start_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.write().await;
        if task_guard.is_some() {
            return;
        }

        let cache = Arc::clone(&self.inner);
        let interval = {
            let c = cache.read().await;
            c.config.eviction_check_interval
        };

        let handle = tokio::spawn(async move {
            let mut interval_timer = time::interval(interval);
            loop {
                interval_timer.tick().await;
                let mut cache = cache.write().await;
                cache.evict_expired();
            }
        });

        *task_guard = Some(handle);
    }

    pub async fn stop_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.write().await;
        if let Some(handle) = task_guard.take() {
            handle.abort();
        }
    }
}

impl<V> Drop for AsyncLRUCache<V> {
    fn drop(&mut self) {
        if let Some(handle) = self.eviction_task.blocking_write().take() {
            handle.abort();
        }
    }
}
