// src/main.rs
use lru_cache_ttl::*;
use std::time::Duration;
use tokio::time::sleep;

#[tokio::main]
async fn main() {
    println!("Running LRU Cache tests...");
    run_tests().await;
    println!("All tests passed!");
}

async fn run_tests() {
    // Basic get/put
    let cache = AsyncLRUCache::new(CacheConfig {
        max_entries: 3,
        default_ttl: Duration::from_millis(100),
        ..Default::default()
    });

    cache.put("a".to_string(), "hello".to_string(), None, None).await;
    let val = cache.get("a").await;
    assert_eq!(val, Some("hello".to_string()), "basic get");
    assert_eq!(cache.size().await, 1, "size after put");

    // LRU eviction
    cache.put("b".to_string(), "world".to_string(), None, None).await;
    cache.put("c".to_string(), "foo".to_string(), None, None).await;
    cache.put("d".to_string(), "bar".to_string(), None, None).await; // should evict 'a'
    assert!(!cache.has("a").await, "lru eviction");
    assert!(cache.has("d").await, "newest kept");

    // TTL expiration
    cache.clear().await;
    cache.put("x".to_string(), "temp".to_string(), Some(Duration::from_millis(50)), None).await;
    sleep(Duration::from_millis(80)).await;
    assert_eq!(cache.get("x").await, None, "ttl expired");

    // Access order
    cache.clear().await;
    cache.put("1".to_string(), "one".to_string(), None, None).await;
    cache.put("2".to_string(), "two".to_string(), None, None).await;
    cache.put("3".to_string(), "three".to_string(), None, None).await;
    cache.get("1").await; // access '1', making '2' the LRU
    cache.put("4".to_string(), "four".to_string(), None, None).await; // should evict '2'
    assert!(!cache.has("2").await, "access order eviction");
    assert!(cache.has("1").await, "accessed item kept");

    // Stats
    let stats = cache.get_stats().await;
    assert!(stats.hits > 0, "has hits");
    assert!(stats.misses > 0, "has misses");

    // Eviction loop
    let cache2 = AsyncLRUCache::new(CacheConfig {
        max_entries: 10,
        default_ttl: Duration::from_millis(50),
        eviction_check_interval: Duration::from_millis(30),
        ..Default::default()
    });
    cache2.put("e1".to_string(), "val1".to_string(), None, None).await;
    cache2.start_eviction_loop().await;
    sleep(Duration::from_millis(150)).await;
    assert!(!cache2.has("e1").await, "eviction loop cleared expired");
    cache2.stop_eviction_loop().await;

    println!("All tests passed");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_basic_get_put() {
        let cache = AsyncLRUCache::new(CacheConfig::default());
        cache.put("key1".to_string(), "value1".to_string(), None, None).await;
        assert_eq!(cache.get("key1").await, Some("value1".to_string()));
    }

    #[tokio::test]
