        let cache = AsyncLRUCache::new(CacheConfig {
            max_entries: 2,
            ..Default::default()
        });

        cache.put("a".to_string(), "1".to_string(), None, None).await;
        cache.put("b".to_string(), "2".to_string(), None, None).await;
        cache.put("c".to_string(), "3".to_string(), None, None).await;

        assert!(!cache.has("a").await);
        assert!(cache.has("b").await);
        assert!(cache.has("c").await);
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let cache = AsyncLRUCache::new(CacheConfig::default());
        cache.put(
            "temp".to_string(),
            "value".to_string(),
            Some(Duration::from_millis(50)),
            None
        ).await;

        assert!(cache.has("temp").await);
        sleep(Duration::from_millis(100)).await;
        assert!(!cache.has("temp").await);
    }

    #[tokio::test]
    async fn test_access_order() {
        let cache = AsyncLRUCache::new(CacheConfig {
            max_entries: 3,
            ..Default::default()
        });

        cache.put("a".to_string(), "1".to_string(), None, None).await;
        cache.put("b".to_string(), "2".to_string(), None, None).await;
        cache.put("c".to_string(), "3".to_string(), None, None).await;

        cache.get("a").await; // Move 'a' to front
        cache.put("d".to_string(), "4".to_string(), None, None).await;

        assert!(cache.has("a").await);
        assert!(!cache.has("b").await); // 'b' should be evicted
    }

    #[tokio::test]
    async fn test_stats() {
        let cache = AsyncLRUCache::new(CacheConfig::default());

        cache.put("k1".to_string(), "v1".to_string(), None, None).await;
        cache.get("k1").await; // hit
        cache.get("k2").await; // miss

        let stats = cache.get_stats().await;
        assert_eq!(stats.hits, 1);
        assert_eq!(stats.misses, 1);
    }

    #[tokio::test]
    async fn test_clear() {
        let cache = AsyncLRUCache::new(CacheConfig::default());

        cache.put("a".to_string(), "1".to_string(), None, None).await;
        cache.put("b".to_string(), "2".to_string(), None, None).await;

        assert_eq!(cache.size().await, 2);
        cache.clear().await;
        assert_eq!(cache.size().await, 0);
    }

    #[tokio::test]
    async fn test_memory_eviction() {
        let cache = AsyncLRUCache::new(CacheConfig {
            max_memory_bytes: 100,
            ..Default::default()
        });

        cache.put("a".to_string(), "x".repeat(30), None, Some(60)).await;
        cache.put("b".to_string(), "y".repeat(30), None, Some(60)).await;

        assert!(!cache.has("a").await); // Should be evicted due to memory
        assert!(cache.has("b").await);
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let cache = AsyncLRUCache::new(CacheConfig {
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        });

        cache.put("temp".to_string(), "value".to_string(), None, None).await;
        cache.start_eviction_loop().await;

        sleep(Duration::from_millis(150)).await;
        assert!(!cache.has("temp").await);

        cache.stop_eviction_loop().await;
    }
}
